import { useState, useRef, useEffect } from 'react';
import { verifyBulk, pollJob, exportUrl } from '../api';

const CATEGORIES = ['all', 'valid', 'invalid', 'risky', 'catchall'];

export default function BulkVerify() {
  const [dragging, setDragging] = useState(false);
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [job, setJob] = useState(null);
  const [error, setError] = useState('');
  const fileRef = useRef();
  const pollRef = useRef();

  const handleFile = (f) => {
    if (!f || !f.name.endsWith('.csv')) {
      setError('Only .csv files accepted');
      return;
    }
    setFile(f);
    setError('');
    setJob(null);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    handleFile(e.dataTransfer.files[0]);
  };

  const handleUpload = async () => {
    if (!file) return;
    setUploading(true);
    setError('');
    try {
      const data = await verifyBulk(file);
      setJob({ id: data.job_id, total: data.total, progress: 0, status: 'processing', percent: 0 });
    } catch (e) {
      setError(e.message || 'Upload failed');
      setUploading(false);
    }
  };

  useEffect(() => {
    if (!job || job.status === 'done') {
      setUploading(false);
      return;
    }
    pollRef.current = setInterval(async () => {
      try {
        const data = await pollJob(job.id);
        setJob(prev => ({ ...prev, ...data }));
        if (data.status === 'done') {
          clearInterval(pollRef.current);
          setUploading(false);
        }
      } catch {}
    }, 1500);
    return () => clearInterval(pollRef.current);
  }, [job?.id, job?.status]);

  const reset = () => {
    setFile(null);
    setJob(null);
    setError('');
    setUploading(false);
  };

  const pct = job ? Math.round((job.progress / job.total) * 100) : 0;

  return (
    <div>
      <p style={{ color: 'var(--text-muted)', marginBottom: 24, fontSize: 13 }}>
        Upload a CSV with one email per row. Up to 50,000 emails. Results split into valid, invalid, risky, and catch-all categories.
      </p>

      {!job && (
        <>
          <div
            onDragOver={e => { e.preventDefault(); setDragging(true); }}
            onDragLeave={() => setDragging(false)}
            onDrop={handleDrop}
            onClick={() => fileRef.current.click()}
            style={{
              border: `2px dashed ${dragging ? 'var(--accent)' : file ? 'var(--green)' : 'var(--border-mid)'}`,
              borderRadius: 'var(--radius-lg)',
              padding: '48px 24px',
              textAlign: 'center',
              cursor: 'pointer',
              transition: 'all 0.2s',
              background: dragging ? 'var(--accent-dim)' : file ? 'var(--green-bg)' : 'transparent',
            }}
          >
            <input ref={fileRef} type="file" accept=".csv" style={{ display: 'none' }} onChange={e => handleFile(e.target.files[0])} />
            <div style={{ fontSize: 32, marginBottom: 12 }}>{file ? '📄' : '⬆'}</div>
            {file ? (
              <>
                <div style={{ fontFamily: 'DM Mono', fontSize: 13, color: 'var(--green)', marginBottom: 4 }}>{file.name}</div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{(file.size / 1024).toFixed(1)} KB — click to change</div>
              </>
            ) : (
              <>
                <div style={{ fontFamily: 'Syne', fontSize: 15, fontWeight: 600, marginBottom: 6 }}>Drop your CSV here</div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>or click to browse · one email per row · .csv only</div>
              </>
            )}
          </div>

          {error && (
            <div style={{ marginTop: 12, background: 'var(--red-bg)', border: '1px solid var(--red)', borderRadius: 'var(--radius)', padding: '10px 14px', color: 'var(--red)', fontSize: 13 }}>
              {error}
            </div>
          )}

          <div style={{ display: 'flex', gap: 10, marginTop: 16 }}>
            <button className="btn-primary" onClick={handleUpload} disabled={!file || uploading}>
              {uploading ? <><span className="spinner">↻</span> Uploading...</> : 'Start verification →'}
            </button>
            {file && <button className="btn-ghost" onClick={reset}>Clear</button>}
          </div>

          <div style={{ marginTop: 20, display: 'flex', gap: 20, fontSize: 12, color: 'var(--text-dim)' }}>
            <span>⚡ 30 threads</span>
            <span>⏱ ~2k–8k emails/hr</span>
            <span>🔍 SMTP + MX + catch-all</span>
          </div>
        </>
      )}

      {job && (
        <div className="animate-in">
          <div className="card" style={{ marginBottom: 20 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
              <div>
                <div style={{ fontFamily: 'Syne', fontSize: 15, fontWeight: 600, marginBottom: 2 }}>
                  {job.status === 'done' ? '✓ Verification complete' : 'Verifying emails...'}
                </div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                  {job.progress?.toLocaleString()} / {job.total?.toLocaleString()} processed
                </div>
              </div>
              <div style={{ fontFamily: 'Syne', fontSize: 28, fontWeight: 700, color: job.status === 'done' ? 'var(--accent)' : 'var(--text)' }}>
                {pct}%
              </div>
            </div>

            <div style={{ height: 6, background: 'var(--bg3)', borderRadius: 99, overflow: 'hidden' }}>
              <div style={{
                height: '100%',
                width: `${pct}%`,
                background: job.status === 'done' ? 'var(--green)' : 'var(--accent)',
                borderRadius: 99,
                transition: 'width 0.4s ease',
              }} />
            </div>
          </div>

          {job.status === 'done' && (
            <div className="animate-in">
              <div style={{ fontFamily: 'Syne', fontSize: 13, fontWeight: 600, color: 'var(--text-muted)', marginBottom: 12, letterSpacing: '0.08em', textTransform: 'uppercase' }}>
                Export results
              </div>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                {CATEGORIES.map(cat => (
                  <a key={cat} href={exportUrl(job.id, cat)} download>
                    <button className="btn-export">
                      ↓ {cat === 'all' ? 'All results' : cat.charAt(0).toUpperCase() + cat.slice(1)}
                    </button>
                  </a>
                ))}
              </div>
              <button className="btn-ghost" onClick={reset} style={{ marginTop: 16 }}>
                ← Verify another list
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
